-- Ships these rules to databases where `authz sync` does not run after migrations yet.

CREATE OR REPLACE FUNCTION public.check_employee_type_system_type(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- The Admin system type is Full on every page, so setting or clearing a
  -- systemType is a server-only write. Reads the request role, as
  -- check_employee_type_change does.
  IF current_setting('role', true) IN ('anon', 'authenticated')
     AND (
       (p_operation = 'INSERT' AND p_new->>'systemType' IS NOT NULL)
       OR (p_operation = 'UPDATE'
           AND (p_new->>'systemType') IS DISTINCT FROM (p_old->>'systemType'))
     ) THEN
    RAISE EXCEPTION 'An employee type''s system type can only be set by the server'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
END;
$function$;

-- apiKey
DO $authz$
DECLARE p record;
BEGIN
  FOR p IN SELECT policyname FROM pg_policies WHERE schemaname = 'public' AND tablename = 'apiKey' LOOP
    EXECUTE format('DROP POLICY %I ON public.%I', p.policyname, 'apiKey');
  END LOOP;
END
$authz$;
ALTER TABLE public."apiKey" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "SELECT" ON "public"."apiKey" FOR SELECT USING ("companyId" = ANY ((SELECT get_companies_with_module_view(ARRAY['settings']::text[], '{}'::text[]))::text[]));
CREATE POLICY "DELETE" ON "public"."apiKey" FOR DELETE USING ("companyId" = ANY ((SELECT get_companies_with_employee_permission('settings.apiKeys_delete'))::text[]));

